def solve(data):
    days, desks, ccys = data["days"], data["desks"], data["currencies"]
    securities = {r["id"]: r for r in data["securities"]}
    marks = {(r["date"], r["security"]): r["price"] for r in data["marks"]}
    fx = {(r["date"], r["currency"]): r["usd_per_unit"] for r in data["fx"]}
    qty = {s: 0.0 for s in securities}
    for r in data["opening_positions"]:
        qty[r["security"]] += r["quantity"]
    cash = {(d, c): 0.0 for d in desks for c in ccys}
    for r in data["opening_cash"]:
        cash[r["desk"], r["currency"]] += r["amount"]
    def nav(date):
        return sum(v * fx[date, c] for (d, c), v in cash.items()) + sum(
            qty[s] * marks[date, s] * fx[date, r["currency"]]
            for s, r in securities.items())
    previous, old_nav = data["opening_date"], nav(data["opening_date"])
    navs, bridges, ledgers, returns = [], [], [], []
    compounded = 1.0
    for date in days:
        bucket = {d: [0.0] * 4 for d in desks}
        exposure = dict(cash)
        for s, r in securities.items():
            d, c = r["desk"], r["currency"]
            exposure[d, c] += qty[s] * marks[previous, s]
            bucket[d][0] += qty[s] * (marks[date, s] - marks[previous, s]) * fx[date, c]
        flow_usd = 0.0
        for r in data["external_flows"]:
            if r["date"] == date:
                d, c, v = r["desk"], r["currency"], r["amount"]
                cash[d, c] += v
                exposure[d, c] += v
                flow_usd += v * fx[previous, c]
        for d in desks:
            bucket[d][3] = sum(exposure[d, c] * (fx[date, c] - fx[previous, c]) for c in ccys)
        for r in data["dividends"]:
            if r["date"] == date:
                s = r["security"]
                d, c = securities[s]["desk"], securities[s]["currency"]
                value = qty[s] * r["per_share"]
                cash[d, c] += value
                bucket[d][2] += value * fx[date, c]
        for r in data["cash_expenses"]:
            if r["date"] == date:
                d, c = r["desk"], r["currency"]
                cash[d, c] -= r["amount"]
                bucket[d][2] -= r["amount"] * fx[date, c]
        for r in data["fills"]:
            if r["date"] == date:
                s, q, p, fee = r["security"], r["quantity"], r["price"], r["fee"]
                d, c = securities[s]["desk"], securities[s]["currency"]
                cash[d, c] -= q * p + fee
                qty[s] += q
                bucket[d][1] += q * (marks[date, s] - p) * fx[date, c]
                bucket[d][2] -= fee * fx[date, c]
        value = nav(date)
        ret = value / (old_nav + flow_usd) - 1.0
        compounded *= 1.0 + ret
        navs.append(value)
        returns.append(ret)
        bridges.extend(x for d in desks for x in bucket[d])
        ledgers.extend(cash[d, c] for d in desks for c in ccys)
        previous, old_nav = date, value
    return {"daily_nav_usd": navs, "daily_desk_pnl_bridge_usd": bridges,
            "daily_cash_local": ledgers,
            "ending_quantities": [qty[s] for s in data["security_order"]],
            "daily_returns": returns, "time_weighted_return": compounded - 1.0}

def solve(data):
    ids, days = data["security_order"], data["days"]
    marks = {(r["date"], r["security"]): r["price"] for r in data["marks"]}
    lots = {s: [] for s in ids}
    for r in sorted(data["opening_lots"], key=lambda r: (r["acquired"], r["lot_id"])):
        lots[r["security"]].append([r["quantity"], r["unit_cost"]])
    cash = data["opening_cash"]
    settlements = [{"date": r["settlement_date"], "amount": r["amount"]}
                   for r in data["opening_unsettled"]]
    dividends = []
    def inventory(date):
        market = sum(sum(q for q, p in lots[s]) * marks[date, s] for s in ids)
        cost = sum(q * p for s in ids for q, p in lots[s])
        return market, market - cost
    previous_unrealized = inventory(data["opening_date"])[1]
    navs, bridges, balances = [], [], []
    for date in days:
        realized, dividend_income, fees = 0.0, 0.0, 0.0
        for r in data["splits"]:
            if r["date"] == date:
                for lot in lots[r["security"]]:
                    lot[0] *= r["ratio"]
                    lot[1] /= r["ratio"]
        for r in data["dividends"]:
            if r["ex_date"] == date:
                value = sum(q for q, p in lots[r["security"]]) * r["per_share"]
                dividends.append({"date": r["payment_date"], "amount": value})
                dividend_income += value
        trades = sorted((r for r in data["trades"] if r["trade_date"] == date),
                        key=lambda r: (r["sequence"], r["trade_id"]))
        for r in trades:
            s, q, p = r["security"], r["quantity"], r["price"]
            fees += r["fee"]
            settlements.append({"date": r["settlement_date"], "amount": -q * p - r["fee"]})
            if q > 0:
                lots[s].append([q, p])
            else:
                remaining, removed_cost = -q, 0.0
                while remaining > 1e-10:
                    amount = min(remaining, lots[s][0][0])
                    removed_cost += amount * lots[s][0][1]
                    lots[s][0][0] -= amount
                    remaining -= amount
                    if lots[s][0][0] < 1e-10:
                        lots[s].pop(0)
                realized += (-q) * p - removed_cost
        for queue in (settlements, dividends):
            for r in queue:
                if r["date"] == date:
                    cash += r["amount"]
        settlements = [r for r in settlements if r["date"] > date]
        dividends = [r for r in dividends if r["date"] > date]
        receivable = sum(max(r["amount"], 0.0) for r in settlements)
        payable = -sum(min(r["amount"], 0.0) for r in settlements)
        dividend_receivable = sum(r["amount"] for r in dividends)
        market, unrealized = inventory(date)
        navs.append(cash + receivable - payable + dividend_receivable + market)
        bridges.extend([realized, unrealized - previous_unrealized, dividend_income, -fees])
        balances.extend([cash, receivable, payable, dividend_receivable, market])
        previous_unrealized = unrealized
    ending = []
    for s in ids:
        q = sum(q for q, p in lots[s])
        basis = sum(q * p for q, p in lots[s])
        ending.extend([q, basis, q * marks[days[-1], s] - basis])
    headroom = max(0.0, cash - payable - data["minimum_cash_reserve"])
    return {"daily_nav_usd": navs, "daily_pnl_bridge_usd": bridges,
            "daily_balance_sheet_usd": balances, "ending_security_ledger": ending,
            "cash_distribution_headroom_usd": headroom,
            "can_pay_requested_distribution": headroom >= data["requested_distribution"]}
